 "content": "import time

from flask import Blueprint, jsonify, request

from src.billing.refunds import refund

from .errors import problem
from .invoices import _INVOICES

bp = Blueprint("refunds", __name__)

IDEMPOTENCY_TTL_SECONDS = 24 * 60 * 60

# idempotency key -> (stored_at, response body, status code)
_IDEMPOTENT_RESPONSES = {}


@bp.route("/invoices/<invoice_id>/refunds", methods=["POST"])
def create_refund(invoice_id):
    key = request.headers.get("X-Acme-Idempotency")
    if not key:
        return problem(428, "Idempotency key required", "Send an X-Acme-Idempotency header.")

    now = time.time()
    stored = _IDEMPOTENT_RESPONSES.get(key)
    if stored and now - stored[0] < IDEMPOTENCY_TTL_SECONDS:
        return jsonify(stored[1]), stored[2]

    # TODO: take the actor from the authenticated principal once the API has auth.
    actor_id = request.headers.get("X-Acme-Actor-Id")
    if not actor_id:
        return problem(400, "Actor required", "Send an X-Acme-Actor-Id header.")

    invoice = _INVOICES.get(invoice_id)
    if invoice is None:
        return problem(404, "Invoice not found", f"No invoice with id {invoice_id}.")

    body = request.get_json(silent=True) or {}
    amount = body.get("amount")
    minor = amount.get("minor") if isinstance(amount, dict) else None
    if type(minor) is not int or minor <= 0:
        return problem(422, "Invalid amount", '`amount` must be {"minor": <positive integer>, "ccy": "USD"}.')
    if amount.get("ccy") != "USD":
        return problem(422, "Unsupported currency", "Refunds must be in the invoice currency (USD).")

    try:
        result = refund(invoice, minor, actor_id=actor_id)
    except ValueError as exc:
        return problem(422, "Refund not allowed", str(exc))

    resp_body = {
        "invoice_id": result["invoice_id"],
        "amount": {"minor": result["refunded_cents"], "ccy": "USD"},
        "status": result["status"],
    }
    status_code = 202 if result["status"] == "pending_approval" else 201
    _IDEMPOTENT_RESPONSES[key] = (now, resp_body, status_code)
    return jsonify(resp_body), status_code
